/**
 * Database ids. Always generated by the backend (never by the AI — spec rule
 * "Do not invent event IDs or database IDs"). Format: `<prefix>_<20 base32 chars>`.
 */
import { randomBytes } from "node:crypto";

const ALPHABET = "0123456789abcdefghjkmnpqrstvwxyz"; // Crockford base32, lower-case

export type IdPrefix =
  | "usr"
  | "ws"
  | "inv"
  | "key"
  | "chn"
  | "ctc"
  | "cnv"
  | "msg"
  | "fil"
  | "evt"
  | "col"
  | "rec"
  | "rvw"
  | "aut"
  | "arun"
  | "whk"
  | "dlv"
  | "ntf"
  | "thr"
  | "de";

export function newId(prefix: IdPrefix): string {
  const bytes = randomBytes(13);
  let out = "";
  let bits = 0;
  let value = 0;
  for (const b of bytes) {
    value = ((value << 8) | b) & 0xffff;
    bits += 8;
    while (bits >= 5 && out.length < 20) {
      out += ALPHABET[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  return `${prefix}_${out}`;
}

/** URL-safe slug from a name, e.g. "Acme Traders!" → "acme-traders". */
export function slugify(name: string): string {
  return (
    name
      .normalize("NFKD")
      .replace(/[̀-ͯ]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 40) || "workspace"
  );
}
